import java.text.DecimalFormat;
import java.util.Random;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Precompute theoretical probabilities based on possible dice combinations
        int[] sumCounts = {0, 0, 1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1}; // 2-12
        double[] theoretical = new double[13];
        for (int i = 2; i <= 12; i++) {
            theoretical[i] = (double) sumCounts[i] / 36.0;
        }

        DecimalFormat df = new DecimalFormat("#.####");
        Random rand = new Random();
        Scanner scanner = new Scanner(System.in);

        // Print theoretical probability distribution
        System.out.println("Theoretical Probability Distribution");
        System.out.println("X\tP(X)");
        System.out.println("-------------------");
        for (int x = 2; x <= 12; x++) {
            System.out.println(x + "\t" + df.format(theoretical[x]));
        }

        // Prompt user for number of simulations
        int numSimulations = 3; // Default
        System.out.print("\nEnter number of simulations to run (default: 3): ");
        try {
            numSimulations = Integer.parseInt(scanner.nextLine());
        } catch (NumberFormatException e) {
            System.out.println("Invalid input. Defaulting to 3 simulations.");
        }

        // Prompt user for roll counts for each simulation
        int[] simulations = new int[numSimulations];
        for (int i = 0; i < numSimulations; i++) {
            System.out.print("Enter number of rolls for simulation " + (i+1) + " (e.g., 36, 500, 10000): ");
            try {
                simulations[i] = Integer.parseInt(scanner.nextLine());
            } catch (NumberFormatException e) {
                // Fallback to default if invalid
                simulations[i] = new int[]{36, 500, 10000}[i % 3];
                System.out.println("Invalid input. Using default value: " + simulations[i]);
            }
        }

        // Run and display results for each simulation
        for (int numRolls : simulations) {
            int[] counts = new int[13];

            // Simulate dice rolls
            for (int i = 0; i < numRolls; i++) {
                int d1 = 1 + rand.nextInt(6);
                int d2 = 1 + rand.nextInt(6);
                int sum = d1 + d2;
                counts[sum]++;
            }

            // Print simulation results
            System.out.println("\nSimulation of " + numRolls + " rolls:");
            System.out.println("X\tCount\tEm Prob\tP(X)");
            System.out.println("--------------------------------------------------");

            for (int x = 2; x <= 12; x++) {
                double emProb = (double) counts[x] / numRolls;
                String emStr = df.format(emProb);
                String tStr = df.format(theoretical[x]);

                // Format X and Count
                System.out.print(x + "\t" + counts[x]);

                // Adjust tabs after Count based on its length
                if (counts[x] < 10) {
                    System.out.print("\t\t\t"); // 3 tabs for single-digit counts
                } else if (counts[x] < 100) {
                    System.out.print("\t\t"); // 2 tabs for 2-digit counts
                } else if (counts[x] < 1000) {
                    System.out.print("\t"); // 1 tab for 3-digit counts
                } else {
                    System.out.print("\t"); // 1 tab for larger counts
                }

                // Print probabilities
                System.out.print(emStr + "\t" + tStr + "\n");
            }
        }
    }
}

