const { workerData } = require('worker_threads');
const papaparse = require('papaparse');
const fs = require('fs');
const path = require('path');
const { Client } = require('pg');
const nodemailer = require('nodemailer');

// Worker data destructuring
const [csvPath, dbConfig, admin] = workerData;
const client = new Client(JSON.parse(dbConfig));
const batchSize = 500;

// Create email transporter
const transporter = nodemailer.createTransport({
    host: 'smtp.example.com',
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS
    }
});

// Email notification function
const sendNotification = async (success, error = null) => {
    const message = {
        from: 'no-reply@company.com',
        to: admin,
        subject: success ? 'Import Success' : 'Import Failed',
        text: success 
            ? 'Customer data has been successfully imported' 
            : `Import error: ${error}`
    };

    try {
        await transporter.sendMail(message);
    } catch (err) {
        console.error('Email notification failed:', err);
    }
};

// Batch insert function
const insertBatch = async (batch) => {
    if (batch.length === 0) return;

    const columns = Object.keys(batch[0]).join(', ');
    const values = batch.map((row, i) => 
        `(${Object.values(row).map((_, j) => 
            `$${i * Object.keys(row).length + j + 1}`
        ).join(', ')})`
    ).join(', ');

    const flatValues = batch.flatMap(Object.values);

    try {
        await client.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
    } catch (err) {
        throw err;
    }
};

// Main processing function
