function sequence = generateMarkovSource(length, transitionProbs, initialState)
    if nargin < 3
        initialState = 0;
    end

    sequence = zeros(1, length);
    current = initialState;

    for i = 1:length
        sequence(i) = current;
        % Generate next state based on transition probabilities
        if current == 0
            current = randsrc(1,1,[0 1; transitionProbs{0}(1) transitionProbs{0}(2)]);
        else
            current = randsrc(1,1,[0 1; transitionProbs{1}(1) transitionProbs{1}(2)]);
        end
    end
end

% CONTEXT ADAPTIVE ARITHMETIC CODING
function [encodedBits] = arithmeticEncode(sequence, transitionProbs)
    low = 0.0;
    high = 1.0;

    % Store the intervals for each symbol
    context = 'initial';

    % Calculate intervals for each symbol in the sequence
    for i = 1:length(sequence)
        symbol = sequence(i);

        % Get probability based on context (previous symbol)
        if isequal(context, 'initial') || context == 0
            p0 = transitionProbs{0}(1);  % Probability of 0 from state 0
        else
            p0 = transitionProbs{1}(1);  % Probability of 0 from state 1
        end

        width = high - low;

        % Update intervals based on the current symbol
        if symbol == 0
            high = low + p0 * width;
        else
            low = low + p0 * width;
        end

        % Update context
        context = symbol;
    end

    % Final value is the midpoint of the interval
    value = (low + high) / 2;

    % Convert to binary representation (32 bits)
    encodedBits = dec2bin(typecast(single(value), 'uint32'), 32);
    encodedBits(encodedBits == ' ') = [];  % Remove spaces
end

% ARITHMETIC DECODING
function decodedSequence = arithmeticDecode(bitstream, length, transitionProbs)
    % Convert bitstream to a decimal value
    value = bin2dec(bitstream) / 2^length;

    low = 0.0;
    high = 1.0;
    decodedSequence = zeros(1, length);

    % Decode each symbol
    for i = 1:length
        % Get probability based on context (previous symbol)
        if i == 1 || decodedSequence(i-1) == 0
            p0 = transitionProbs{0}(1);  % Probability of 0 from state 0
        else
            p0 = transitionProbs{1}(1);  % Probability of 0 from state 1
        end

        width = high - low;
        split = low + p0 * width;

        if value < split
            decodedSequence(i) = 0;
            high = split;
        else
            decodedSequence(i) = 1;
            low = split;
        end
    end
end

% NOISY CHANNEL SIMULATION (BSC)
function receivedBits = bscChannel(bitstream, ber)
    % Convert bitstream to array
    bits = double(bitstream) - 48;  % Convert '0'/'1' to 0/1

    % Generate random numbers for each bit
    errors = rand(size(bits)) < ber;

    % Apply errors (bit flips)
    bits = mod(bits + errors, 2);

    % Convert back to string
    receivedBits = char(bits + 48);
end

% BIT ERROR RATE CALCULATION
function ber = calculateBER(transmitted, received)
    % Ensure both strings are the same length
    maxLength = max(length(transmitted), length(received));
    transmitted = [transmitted, repmat('0', 1, maxLength - length(transmitted))];
    received = [received, repmat('0', 1, maxLength - length(received))];

    % Calculate errors
    errors = sum(transmitted ~= received);

    % Calculate BER
    ber = errors / maxLength;
end

